{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE Maplemonk.blinkit_atovio_sales_Fact_Items AS SELECT CAST(Item_ID AS STRING) AS Item_ID, CAST(HSN_Code AS STRING) AS HSN_Code, CAST(MRP__Rs_ AS FLOAT64) AS MRP, CAST(Order_Id AS STRING) AS Order_ID, CAST(Quantity AS INT64) AS Quantity, CAST(REPLACE(Total_Tax, \'-\', \'0\') AS FLOAT64) AS Total_Tax, cast(left(Order_Date,10) as date) AS Order_Date, CAST(Order_Status AS STRING) AS Order_Status, coalesce(P.name,CAST(Product_Name AS STRING)) AS Product_Name, CAST(Supply_City AS STRING) AS Supply_City, CAST(Customer_City AS STRING) AS Customer_City, CAST(Selling_Price__Rs_ AS FLOAT64) AS Selling_Price_Rs, CAST(Variant_Description AS STRING) AS Variant_Description, CAST(Total_Gross_Bill_Amount AS FLOAT64) AS Total_Gross_Bill_Amount, p.category product_category, p.sub_category, p.style, p.commonsku ,cast(mrp.mrp as float64)*CAST(Quantity AS INT64)mrp_sales ,cast(mrp.msp as float64)*CAST(Quantity AS INT64)msp_sales ,cast(mrp.cogs as float64)*CAST(Quantity AS INT64) total_cogs ,cast(mrp.mrp as float64)*CAST(Quantity AS INT64) - CAST(Selling_Price__Rs_ AS FLOAT64) discount_mrp from maplemonk.blinkit_atovio_new_sales s LEFT JOIN (select * from (select upper(trim(product_title)) as name, upper(trim(category)) category, upper(trim(sub_category)) sub_category, upper(trim(style)) style , upper(trim(primarykey)) as commonsku, trim(upper(blinkit_id)) as blinkit_id, row_number()over (partition by trim(upper(flipkart_fsn)) order by length(ifnull(trim(upper(flipkart_fsn)),\'\')) desc) rw from neon-poetry-482906-j7.Maplemonk.atovio_sku_master where trim(upper(blinkit_id)) is not null ) where rw = 1 ) p ON LOWER(CAST(Item_ID AS STRING)) = lower(p.blinkit_id) left join (select * from maplemonk.mapping_sku_mrp_cogs qualify row_number() over (partition by sku_code order by 1) = 1) mrp on p.commonsku = mrp.sku_code UNION ALL SELECT CAST(NULLIF(Item_ID, \'-\') AS STRING) AS Item_ID, CAST(NULLIF(HSN_Code, \'-\') AS STRING) AS HSN_Code, CAST(NULLIF(MRP__Rs_, \'-\') AS FLOAT64) AS MRP, CAST(Order_ID AS STRING) AS Order_ID, CAST(Quantity AS INT64) AS Quantity, CAST(REPLACE(Total_Tax, \'-\', \'0\') AS FLOAT64) AS Total_Tax, CAST(FORMAT_DATE(\'%Y-%m-%d\', COALESCE( SAFE.PARSE_DATE(\'%d-%b-%y\', NULLIF(order_date, \'-\')), SAFE.PARSE_DATE(\'%d %b %y\', NULLIF(order_date, \'-\')), SAFE.PARSE_DATE(\'%d %B %Y\', NULLIF(order_date, \'-\')) )) as date) AS order_date, CAST(Order_Status AS STRING) AS Order_Status, CAST(Product_Name AS STRING) AS Product_Name, CAST(Supply_City AS STRING) AS Supply_City, CAST(Customer_City AS STRING) AS Customer_City, CAST(Selling_Price__Rs_ AS FLOAT64) AS Selling_Price_Rs, CAST(Variant_Description AS STRING) AS Variant_Description, CAST(Total_Gross_Bill_Amount AS FLOAT64) AS Total_Gross_Bill_Amount, p.category product_category, p.sub_category, p.style, p.commonsku ,cast(mrp.mrp as float64)*CAST(Quantity AS INT64)mrp_sales ,cast(mrp.msp as float64)*CAST(Quantity AS INT64)msp_sales ,cast(mrp.cogs as float64)*CAST(Quantity AS INT64) total_cogs ,cast(mrp.mrp as float64)*CAST(Quantity AS INT64) - CAST(Selling_Price__Rs_ AS FLOAT64) discount_mrp from `Maplemonk.Atovio_db_Blinkit_s3_Sales_Forward_Order` LEFT JOIN (select * from (select upper(trim(product_title)) as name, upper(trim(category)) category, upper(trim(sub_category)) sub_category, upper(trim(style)) style , upper(trim(primarykey)) as commonsku, trim(upper(blinkit_id)) as blinkit_id, row_number()over (partition by trim(upper(flipkart_fsn)) order by length(ifnull(trim(upper(flipkart_fsn)),\'\')) desc) rw from neon-poetry-482906-j7.Maplemonk.atovio_sku_master where trim(upper(blinkit_id)) is not null ) where rw = 1 ) p ON LOWER(CAST(Item_ID AS STRING)) = lower(p.blinkit_id) left join (select * from maplemonk.mapping_sku_mrp_cogs qualify row_number() over (partition by sku_code order by 1) = 1) mrp on p.commonsku = mrp.sku_code ;",
                    "transaction": true
                }
